function supportedBrowserLanguage() {
  const code = (navigator.language || "en").toLowerCase().split("-")[0];
  return STRINGS[code] ? code : "en";
}

export async function createI18n() {
  const saved = await storage.get("app.interface-language", "auto");
  let locale = STRINGS[saved] ? saved : "auto";
  const listeners = new Set();
  const resolved = () => locale === "auto" ? supportedBrowserLanguage() : locale;
  const api = {
    get locale() { return locale; },
    get resolvedLocale() { return resolved(); },
    t(key) {
      return DEFINITION_REFINEMENT_STRINGS[resolved()]?.[key]
        ?? DEFINITION_FALLBACK_STRINGS[resolved()]?.[key]
        ?? PRONUNCIATION_STRINGS[resolved()]?.[key]
        ?? READ_ALOUD_STRINGS[resolved()]?.[key]
        ?? DOWNLOAD_STRINGS[resolved()]?.[key]
        ?? LEARN_EDIT_STATUS_STRINGS[resolved()]?.[key]
        ?? LEARN_EDIT_STRINGS[resolved()]?.[key]
        ?? LEARN_VOCABULARY_STRINGS[resolved()]?.[key]
        ?? LEARN_STUDY_STRINGS[resolved()]?.[key]
        ?? LEARN_STRINGS[resolved()]?.[key]
        ?? DEFINITION_STRINGS[resolved()]?.[key]
        ?? STRINGS[resolved()]?.[key]
        ?? DEFINITION_REFINEMENT_STRINGS.en[key]
        ?? DEFINITION_FALLBACK_STRINGS.en[key]
        ?? PRONUNCIATION_STRINGS.en[key]
        ?? READ_ALOUD_STRINGS.en[key]
        ?? DOWNLOAD_STRINGS.en[key]
        ?? LEARN_EDIT_STATUS_STRINGS.en[key]
        ?? LEARN_EDIT_STRINGS.en[key]
        ?? LEARN_VOCABULARY_STRINGS.en[key]
        ?? LEARN_STUDY_STRINGS.en[key]
        ?? LEARN_STRINGS.en[key]
        ?? DEFINITION_STRINGS.en[key]
        ?? STRINGS.en[key]
        ?? key;
    },
    languageName(code, fallback = "") {
      if (!code) return fallback;
      for (const displayLocale of [resolved(), "en"]) {
        try {
          const name = new Intl.DisplayNames([displayLocale], {
            type: "language",
            fallback: "none",
          }).of(code);
          if (name) return name;
        } catch {
          // Older Chrome versions may not expose Intl.DisplayNames.
        }
      }
      return fallback || code;
    },
    async setLocale(next) {
      locale = STRINGS[next] ? next : "auto";
      await storage.set("app.interface-language", locale);
      listeners.forEach((listener) => listener());
    },
    subscribe(listener) { listeners.add(listener); return () => listeners.delete(listener); },
  };
  return api;
}
